--
-- Triggers `comments`
--
DELIMITER $$
CREATE TRIGGER `after_comment_insert` AFTER INSERT ON `comments` FOR EACH ROW BEGIN
    DECLARE act_type ENUM('comment','reply_comment','like_post','save_news','like_comment');
    DECLARE tgt_type ENUM('post','news','comment');
    DECLARE tgt_id INT;

    -- Kiểm tra nếu là reply hay comment thường
    IF NEW.parent_comment_id IS NOT NULL THEN
        SET act_type = 'reply_comment';
    ELSE
        SET act_type = 'comment';
    END IF;

    -- Xác định target là post hay news
    IF NEW.post_id IS NOT NULL THEN 
        SET tgt_type = 'post';
        SET tgt_id = NEW.post_id;
    ELSE 
        SET tgt_type = 'news';
        SET tgt_id = NEW.news_id;
    END IF;

    INSERT INTO activity_logs (user_id, activity_type, target_type, target_id, description)
    VALUES (NEW.user_id, act_type, tgt_type, tgt_id, NEW.content);
END
$$
DELIMITER ;

