DELIMITER $$
CREATE TRIGGER `after_comment_like` AFTER INSERT ON `comment_likes` FOR EACH ROW BEGIN
    INSERT INTO activity_logs (user_id, activity_type, target_type, target_id, description)
    VALUES (NEW.user_id, 'like_comment', 'comment', NEW.comment_id, 'User liked a comment');
END
$$
DELIMITER ;

