--
-- Triggers `conversionhistory`
--
DELIMITER $$
CREATE TRIGGER `after_conversion` AFTER INSERT ON `conversionhistory` FOR EACH ROW BEGIN
    INSERT INTO activity_logs (user_id, activity_type, target_type, target_id, description)
    VALUES (
        NEW.user_id, 
        'conversion', 
        'post', 
        NEW.history_id, 
        CONCAT('Converted ', NEW.amount_input, ' ', NEW.from_currency, ' to ', NEW.amount_output, ' ', NEW.to_currency)
    );
END
$$
DELIMITER ;

