--
-- Table structure for table `exchangerates`
--

CREATE TABLE `exchangerates` (
  `rate_id` int(11) NOT NULL,
  `base_currency` varchar(3) DEFAULT NULL,
  `target_currency` varchar(3) DEFAULT NULL,
  `exchange_rate` decimal(18,6) NOT NULL,
  `source` varchar(50) DEFAULT NULL,
  `bid_price` decimal(18,6) DEFAULT NULL,
  `ask_price` decimal(18,6) DEFAULT NULL,
  `change_24h` decimal(10,4) DEFAULT NULL,
  `last_updated` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `volume_24h` decimal(20,2) DEFAULT NULL COMMENT '24h trading volume in USD',
  `volatility` enum('Low','Medium','High') DEFAULT 'Low',
  `price_change_percent` decimal(10,4) DEFAULT NULL COMMENT '24h price change percentage',
  `trend` enum('up','down','neutral') DEFAULT 'neutral'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

