DELIMITER $$
CREATE TRIGGER `after_news_favorite` AFTER INSERT ON `favorites` FOR EACH ROW BEGIN
    INSERT INTO activity_logs (user_id, activity_type, target_type, target_id, description)
    VALUES (NEW.user_id, 'save_news', 'news', NEW.news_id, 'User saved a news article');
END
$$
DELIMITER ;

